var n=[{title:`Vad ”failure” betyder`,text:`Koncentriskt failure är när du försöker men inte kan genomföra en lyftrepetition till. Tekniskt failure kommer tidigare, när du inte längre kan hålla det planerade omfånget eller en säker rörelse. I ett komplext lyft kan du nå tekniskt failure långt innan målmusklerna når fullt muskulärt failure.`},{title:`Hård träning utan failure`,text:`I ACSM:s ställningstagande 2026 gav träning till momentant failure inte på ett pålitligt sätt bättre resultat i styrka, hypertrofi eller power. Set som slutar med ungefär två eller tre repetitioner i reserv ger ofta en användbar träningsstimulans med mindre trötthet. Hur nära failure du bör gå beror på ditt mål, belastningen, övningen, din erfarenhet och situationen.`},{title:`Risken varierar med övningen`,text:`Att gå nära failure i en stabil maskin eller en isolationsövning med låg risk är mycket annorlunda än i en tung skivstångsknäböj, en ostödd press över huvudet eller en obekant explosiv rörelse. Att tappa bålspänningen, tappa kontrollen på vägen ner eller sakna ett säkert sätt att avbryta är skäl att avsluta ett set. Om du tränar ensam utan säkerhetsutrustning är det ännu ett skäl att behålla repetitioner i reserv.`},{title:`Exempel`,text:`Om du ror 15 kg i tolv rena repetitioner och tror att du hade klarat två till är setet runt 2 RIR. Du behöver inte bevisa det genom att tvinga fram repetition tretton och fjorton. En erfaren tränande kan ibland ta ett set nära failure i en säker maskin av ett särskilt skäl, men det ska inte vara planen för varje pass. Sikta på ansträngning och kvalitet som du kan upprepa, och betrakta inte failure som en prestation att samla på.`},{title:`När du ska sluta`,text:`Avsluta varje set om du får ovanlig smärta, yrsel, plötslig svaghet eller inte kan kontrollera rörelsen. Normal muskelansträngning är något annat än dessa varningstecken.`}];var r=[{label:`ACSM:s ställningstagande 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Studie om RIR-baserad RPE`,url:`https://pubmed.ncbi.nlm.nih.gov/26049792/`}];var a={sections:n,sources:r};export{a as default,n as sections,r as sources};